sys_script_include.script:
var TriageUtils = Class.create();
TriageUtils.prototype = {
    initialize: function() {},

    // Returns the number of active incidents for a caller (sys_user sys_id)
    getOpenIncidentCount: function(userSysId) {
        var count = 0;
        var ga = new GlideAggregate('incident');
        ga.addQuery('caller_id', userSysId);
        ga.addQuery('active', true);
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) {
            count = parseInt(ga.getAggregate('COUNT'), 10) || 0;
        }
        return count;
    },

    type: 'TriageUtils'
};
